import{_ as i,C as n,o as l,c as h,j as t,a as o,E as a,ak as r}from"./chunks/framework.DxrHb2fb.js";const g=JSON.parse('{"title":"Marquee 跑马灯","description":"","frontmatter":{},"headers":[],"relativePath":"components/marquee.md","filePath":"components/marquee.md","lastUpdated":1789479328000}'),s={name:"components/marquee.md"},u={id:"marquee-跑马灯",tabindex:"-1"};function p(b,e,m,q,f,x){const c=n("Badge"),d=n("XhDemo");return l(),h("div",null,[t("h1",u,[e[0]||(e[0]=o("Marquee 跑马灯 ",-1)),a(c,{type:"info",text:"alpha"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#marquee-跑马灯","aria-label":'Permalink to "Marquee 跑马灯 <Badge type="info" text="alpha" />"'},"​",-1))]),e[3]||(e[3]=r('<p>内容沿一条轴循环滚动。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/marquee" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/marquee.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/marquee" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/marquee" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/marquee.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>窗口只显示一段，轨道在其中向左滚动；滚动整段在皮肤的 @keyframes 中，使用者不写动画</p>',4)),a(d,{src:"marquee/01-basic"}),e[4]||(e[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;marquee&quot;</code>：<strong><code>root</code></strong> · <strong><code>content</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="方向" tabindex="-1">方向 <a class="header-anchor" href="#方向" aria-label="Permalink to &quot;方向&quot;">​</a></h3><p>四档：左右沿横轴，上下沿纵轴。轴另写为 data-orientation，竖向滚动的窗口依靠 --xh-marquee-block-size 定高</p>',6)),a(d,{src:"marquee/02-direction"}),e[5]||(e[5]=t("h3",{id:"重复铺满",tabindex:"-1"},[o("重复铺满 "),t("a",{class:"header-anchor",href:"#重复铺满","aria-label":'Permalink to "重复铺满"'},"​")],-1)),e[6]||(e[6]=t("p",null,"autoFill 在轨道中铺设两份内容，滚完一份时第二份正好位于起点，看不出接缝；不开启则整段滚完再回到起点",-1)),a(d,{src:"marquee/03-auto-fill"}),e[7]||(e[7]=t("h3",{id:"速度与暂停",tabindex:"-1"},[o("速度与暂停 "),t("a",{class:"header-anchor",href:"#速度与暂停","aria-label":'Permalink to "速度与暂停"'},"​")],-1)),e[8]||(e[8]=t("p",null,"speed 是每秒像素；pauseOnHover 在指针停下或焦点落进窗口时暂停",-1)),a(d,{src:"marquee/04-speed-and-pause"}),e[9]||(e[9]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>公告条、合作方 logo 墙等内容多、位置窄且不要求逐条读完的展示。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>内容重要且必须被读到：滚动文字阅读费力，且会滚走。</li><li>需要用户处理的通知使用<a href="./alert">警告提示</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><code>autoFill</code> 自动重复内容铺满容器，接缝处不留空。</li><li><code>direction</code> 切换方向，<code>speed</code> 调整速度；速度按 <code>--xh-marquee-span</code> 换算为一圈时长，需要精确对应每秒像素数时把该槽改为内容的真实长度。</li><li><code>pauseOnHover</code> 悬停暂停，<code>paused</code> 由作者控制，受控状态优先于悬停。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>内部放<a href="./image">图片</a>组成 logo 墙，或<a href="./badge">徽标</a>组成标签流。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>必须可以暂停，悬停暂停是最低要求。</li><li>系统开启减弱动效时应停止。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用它承载唯一的重要信息（故障公告、截止时间）。</li><li>速度过快，无法读完一句话。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-marquee&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMarqueeContent</code> <code>XhMarqueeRoot</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/marquee.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>autoFill</code></td><td><code>boolean</code></td><td></td><td>内容不足时重复铺满：轨道中铺两份内容，走完一份正好接上第二份。</td></tr><tr><td><code>direction</code></td><td><code>MarqueeDirection</code></td><td></td><td>滚动方向，默认 left。</td></tr><tr><td><code>paused</code></td><td><code>boolean</code></td><td></td><td>受控暂停：为真即停在当前位置，为假继续移动。优先于 pauseOnHover。</td></tr><tr><td><code>pauseOnHover</code></td><td><code>boolean</code></td><td></td><td>指针停在窗口上时暂停；键盘焦点落进窗口时同样暂停。</td></tr><tr><td><code>speed</code></td><td><code>number</code></td><td></td><td>名义上的每秒像素数。写为根上的内联变量，皮肤用一份内容的长度除以它换算为一圈的时长。 该长度取自 <code>--xh-marquee-span</code>：CSS 无法读取布局尺寸，槽中存放的是一个默认值。 把它修改为与内容真实长度一致时速度才逐字等于每秒该像素数，否则它是一个成比例的快慢档。 只接受有限正数；其余值不写出，回退为皮肤默认值。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>copies</code></td><td><code>number</code></td><td>轨道中铺设的内容份数：autoFill 开启为 2，关闭为 1。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/marquee.css</code> 使用 <code>[data-scope=&quot;marquee&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 与 <code>xihan.motion</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-marquee-block-size</code></td><td><code>root</code></td><td><code>block-size</code></td><td><code>orientation=vertical</code></td><td><code>10rem</code></td><td>marquee 的 root 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-marquee-gap</code></td><td><code>content</code><br><code>root</code></td><td><code>padding-block-end</code><br><code>padding-inline-end</code></td><td><code>orientation=vertical</code><br><code>xh-copy</code></td><td><code>--xh-space-6</code></td><td>marquee 的 content、root 部件 padding-block-end、padding-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-marquee-span</code></td><td><code>content</code><br><code>root</code></td><td><code>animation-duration</code></td><td><code>auto-fill</code><br><code>default</code></td><td><code>600</code></td><td>marquee 的 content、root 部件 animation-duration 覆盖槽。</td></tr><tr><td><code>--xh-marquee-speed</code></td><td><code>content</code><br><code>root</code></td><td><code>animation-duration</code></td><td><code>auto-fill</code><br><code>default</code></td><td><code>60</code></td><td>marquee 的 content、root 部件 animation-duration 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>关键帧 <code>xh-marquee-x</code> · <code>xh-marquee-y</code> 随皮肤自带，不引用别处文件里的名字。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><p>皮肤另按输入能力分档：<code>hover: hover</code>：同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',38))])}const P=i(s,[["render",p]]);export{g as __pageData,P as default};
